mapper.select:
SELECT id, user_id, title, file_type, file_url, file_size, subject_code, parse_status, error_msg, chunk_count, is_public, created_at
FROM kb_document
WHERE 1=1

    AND is_public = #{isPublic}


    AND user_id = #{userId}


    AND subject_code = #{subjectCode}


    AND title LIKE CONCAT('%', #{keyword}, '%')

ORDER BY created_at DESC

SELECT id, user_id, title, file_type, file_url, file_size, subject_code, parse_status, error_msg, chunk_count, is_public, created_at
FROM kb_document
WHERE id = #{id}
